// Local server for the pony pose atlas / animator page (no external packages).
//  - serves the page generated by Remains.Editor.PonyPoseAtlas.RunBatch (.reference/affine-points/pose-atlas.html);
//  - keeps own states, poses, marks and clips as project files (RemainsUnity/.../PonyAnimation/Authored);
//  - keeps one live pose per session (each agent its own; the user's page is "main" unless it opens ?session=...),
//    relays it between the pages of that session and runs the session's agent commands in one of its pages (a visible
//    one, else a hidden tab of a headless Chrome), so the page stays the single implementation of posing.
// Start: node Tools/PoseAnimator/server.mjs  (mcp.mjs starts it when needed). Listens on 127.0.0.1 only.
import http from 'node:http';
import fs from 'node:fs';
import fsp from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import {createHash} from 'node:crypto';
import {spawn} from 'node:child_process';
import {fileURLToPath} from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
export const PORT = +(process.env.POSE_ANIMATOR_PORT || 8770);
// Two layouts: the project (Tools/PoseAnimator, page from the Unity batch, work in Authored/) and the standalone
// public tool (server/ beside index.html and work/, built by build-site.mjs). POSE_ANIMATOR_PAGE / _STORE override both.
const standalone = fs.existsSync(path.join(here, '..', 'index.html'));
const root = standalone ? path.resolve(here, '..') : path.resolve(here, '../..');
const PAGE = process.env.POSE_ANIMATOR_PAGE || (standalone ? path.join(root, 'index.html') : path.join(root, '.reference/affine-points/pose-atlas.html'));
const STORE = process.env.POSE_ANIMATOR_STORE || (standalone ? path.join(root, 'work') : path.join(root, 'RemainsUnity/Assets/Remains/Editor/PonyAnimation/Authored'));
const CLIPS = path.join(STORE, 'clips');
const BROWSERS = [process.env.POSE_ANIMATOR_BROWSER, 'C:/Program Files/Google/Chrome/Application/chrome.exe',
  'C:/Program Files (x86)/Google/Chrome/Application/chrome.exe', 'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe',
  'C:/Program Files/Microsoft/Edge/Application/msedge.exe'].filter(Boolean);
const COMMAND_TIMEOUT = 60000, WORKER_WAIT = 30000;

const clients = new Map();      // id -> {res, headless, session}
const pending = new Map();      // command id -> {resolve, timer}
const sessions = new Map();     // name -> {snap, frame, clip, client}
const opening = new Set();      // sessions whose headless tab is being opened
let nextCommand = 1, headlessChild = null, debugPort = null;
// Full-work and baked-clip writes share one queue. A stale client must never erase another session's work.
let workQueue = Promise.resolve();
function withWorkLock(action) { const result = workQueue.then(action); workQueue = result.catch(() => {}); return result; }
const sessionName = value => (value || 'main').toLowerCase().replace(/[^a-z0-9_-]/g, '') || 'main';

const log = (...a) => console.log(new Date().toISOString(), ...a);
const readJson = async (file, fallback) => { try { return JSON.parse(await fsp.readFile(file, 'utf8')); } catch (e) { if (e.code !== 'ENOENT') throw new Error(`Файл ${file} повреждён: ${e.message}`); return fallback; } };
// Pretty, stable JSON keeps project diffs readable; unchanged files are not rewritten.
async function writeJson(file, value) {
  const text = JSON.stringify(value, null, 1) + '\n';
  try { if (await fsp.readFile(file, 'utf8') === text) return; } catch {}
  await fsp.mkdir(path.dirname(file), {recursive: true});
  const temporary = file + '.tmp';
  try { await fsp.writeFile(temporary, text, 'utf8'); await fsp.rename(temporary, file); }
  finally { await fsp.unlink(temporary).catch(error => { if (error.code !== 'ENOENT') throw error; }); }
}
const clipFile = id => { if (!/^[a-z0-9][a-z0-9-]*$/.test(id)) throw new Error('Недопустимый id анимации: ' + id); return path.join(CLIPS, id + '.json'); };
async function clipNames() {
  try { return (await fsp.readdir(CLIPS)).filter(name => name.endsWith('.json')).sort(); }
  catch (error) { if (error.code === 'ENOENT') return []; throw error; }
}
// Hash actual persisted bytes, including baked frames: manual changes and a bake invalidate stale work snapshots too.
async function workRevision() {
  const hash = createHash('sha256');
  for (const name of ['states.json', 'poses.json', 'marks.json', ...(await clipNames()).map(name => 'clips/' + name)]) {
    hash.update(name + '\0');
    try { hash.update(await fsp.readFile(path.join(STORE, name))); }
    catch (error) { if (error.code !== 'ENOENT') throw error; hash.update('<absent>'); }
    hash.update('\0');
  }
  return hash.digest('hex');
}
async function requireRevision(revision) {
  const current = await workRevision();
  if (typeof revision !== 'string' || revision !== current) {
    const error = new Error('Общая работа изменена другой вкладкой или на диске. Сохранение отклонено, чужие данные не затронуты. Скачайте свою работу для восстановления и перенесите правки в актуальную копию.');
    error.status = 409; error.revision = current; throw error;
  }
}

async function loadWork() {
  const clips = {};
  for (const name of await clipNames()) {
    const {frames, ...clip} = await readJson(path.join(CLIPS, name), null);
    clips[clip.id] = {id: clip.id, name: clip.name, length: clip.length, fps: clip.fps, keys: clip.keys, baked: !!frames};
  }
  return {authored: await readJson(path.join(STORE, 'states.json'), []), poses: await readJson(path.join(STORE, 'poses.json'), []),
    marks: await readJson(path.join(STORE, 'marks.json'), {}), clips, current: Object.keys(clips)[0], revision: await workRevision()};
}
async function saveWork(work) {
  if (!Array.isArray(work.authored) || !Array.isArray(work.poses) || !work.clips || typeof work.clips !== 'object' || Array.isArray(work.clips)) throw new Error('Неверная структура работы аниматора.');
  // Validate every destination before changing even the first file.
  for (const [id, clip] of Object.entries(work.clips)) {
    if (!clip || clip.id !== id || !Array.isArray(clip.keys) || !Number.isInteger(clip.length) || clip.length < 2 || clip.length > 600 || !Number.isFinite(clip.fps) || clip.fps <= 0)
      throw new Error('Неверные ключи или время анимации: ' + id);
    clipFile(id);
  }
  await writeJson(path.join(STORE, 'states.json'), work.authored);
  await writeJson(path.join(STORE, 'poses.json'), work.poses);
  await writeJson(path.join(STORE, 'marks.json'), work.marks || {});
  const kept = new Set();
  for (const clip of Object.values(work.clips)) {
    const file = clipFile(clip.id); kept.add(path.basename(file));
    const old = await readJson(file, null);
    const same = old && JSON.stringify([old.keys, old.length, old.fps]) === JSON.stringify([clip.keys, clip.length, clip.fps]);
    // Baked frames stay only while the keys they were baked from are unchanged.
    const value = {format: 'pony-pose-atlas-clip', version: 1, ...(old?.sourceHash ? {sourceHash: old.sourceHash} : {}), id: clip.id, name: clip.name,
      fps: clip.fps, length: clip.length, keys: clip.keys, ...(same && old.frames ? {authored: old.authored, frames: old.frames} : {})};
    await writeJson(file, value);
  }
  for (const name of await clipNames())
    if (!kept.has(name)) { await fsp.unlink(path.join(CLIPS, name)); log('Удалена анимация', name); }
}

function send(res, event, data) { res.write(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`); }
function broadcast(event, data, session) { for (const c of clients.values()) if (!session || c.session === session) send(c.res, event, data); }
// A visible page of the session wins (its user watches), else the session's headless tab.
function worker(session) {
  const list = [...clients.entries()].filter(([, c]) => c.session === session);
  return (list.filter(([, c]) => !c.headless).pop() || list.pop() || [])[0];
}
async function startHeadless() {
  if (headlessChild && headlessChild.exitCode === null && debugPort) return;
  const exe = BROWSERS.find(p => fs.existsSync(p));
  if (!exe) throw new Error('Нет Chrome/Edge для фоновой отрисовки; задайте POSE_ANIMATOR_BROWSER.');
  const profile = path.join(os.tmpdir(), 'remains-pose-animator-browser'), portFile = path.join(profile, 'DevToolsActivePort');
  await fsp.rm(portFile, {force: true});
  headlessChild = spawn(exe, ['--headless=new', '--disable-gpu', '--no-first-run', '--disable-extensions', '--disable-background-networking',
    '--remote-debugging-port=0', `--user-data-dir=${profile}`, 'about:blank'], {windowsHide: true, stdio: 'ignore'});
  headlessChild.on('exit', code => { log('Фоновый браузер завершился, код', code); debugPort = null; });
  for (let i = 0; i < 100 && !debugPort; i++) {
    await new Promise(r => setTimeout(r, 100));
    try { debugPort = +(await fsp.readFile(portFile, 'utf8')).split(/\r?\n/)[0] || null; } catch {}
  }
  if (!debugPort) throw new Error('Фоновый браузер не открыл порт отладки.');
  log('Запущен фоновый браузер', exe, 'порт', debugPort);
}
// One headless Chrome, one tab per agent session (DevTools HTTP endpoint, no protocol client needed).
async function openHeadlessTab(session) {
  if (opening.has(session)) return;
  opening.add(session);
  try {
    await startHeadless();
    const url = `http://127.0.0.1:${PORT}/?headless=1&session=${encodeURIComponent(session)}`;
    const r = await fetch(`http://127.0.0.1:${debugPort}/json/new?${encodeURIComponent(url)}`, {method: 'PUT'});
    if (!r.ok) throw new Error('Фоновый браузер не открыл вкладку: ' + r.status);
    log('Открыта фоновая вкладка сеанса', session);
  } finally { setTimeout(() => opening.delete(session), WORKER_WAIT); }
}
async function runCommand(session, name, args) {
  if (!fs.existsSync(PAGE)) throw new Error('Нет страницы атласа ' + PAGE + '; соберите её: -executeMethod Remains.Editor.PonyPoseAtlas.RunBatch');
  let target = worker(session);
  if (!target) {
    await openHeadlessTab(session);
    const until = Date.now() + WORKER_WAIT;
    while (!(target = worker(session)) && Date.now() < until) await new Promise(r => setTimeout(r, 200));
    if (!target) throw new Error(`Страница аниматора сеанса «${session}» не подключилась за ${WORKER_WAIT / 1000} с.`);
  }
  const id = nextCommand++;
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => { pending.delete(id); reject(new Error(`Команда ${name} не выполнена за ${COMMAND_TIMEOUT / 1000} с.`)); }, COMMAND_TIMEOUT);
    pending.set(id, {resolve, timer});
    send(clients.get(target).res, 'command', {id, name, args});
  });
}

async function body(req) { let text = ''; for await (const chunk of req) text += chunk; return text ? JSON.parse(text) : {}; }
function reply(res, status, value, type = 'application/json; charset=utf-8') {
  res.writeHead(status, {'Content-Type': type, 'Cache-Control': 'no-store'});
  res.end(typeof value === 'string' || Buffer.isBuffer(value) ? value : JSON.stringify(value));
}

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, 'http://127.0.0.1');
  const client = url.searchParams.get('client'), session = sessionName(url.searchParams.get('session'));
  try {
    if (req.method === 'GET' && (url.pathname === '/' || url.pathname === '/pose-atlas.html')) {
      if (!fs.existsSync(PAGE)) return reply(res, 404, 'Нет страницы атласа: соберите её командой Remains.Editor.PonyPoseAtlas.RunBatch.', 'text/plain; charset=utf-8');
      return reply(res, 200, await fsp.readFile(PAGE), 'text/html; charset=utf-8');
    }
    if (url.pathname === '/api/status') return reply(res, 200, {ok: true, storageVersion: 2, page: fs.existsSync(PAGE), clients: [...clients.values()].map(c => ({session: c.session, headless: c.headless})), store: STORE});
    if (url.pathname === '/api/sessions') return reply(res, 200, [...new Set([...sessions.keys(), ...[...clients.values()].map(c => c.session)])].sort());
    if (url.pathname === '/api/work' && req.method === 'GET') return reply(res, 200, await withWorkLock(loadWork));
    if (url.pathname === '/api/work' && req.method === 'PUT') {
      const work = await body(req);
      const revision = await withWorkLock(async () => { await requireRevision(work.revision); await saveWork(work); return workRevision(); });
      broadcast('work', {client, revision}); return reply(res, 200, {ok: true, revision});
    }
    if (url.pathname.startsWith('/api/clip/') && req.method === 'PUT') {
      const {revision: expected, ...clip} = await body(req), id = decodeURIComponent(url.pathname.slice('/api/clip/'.length));
      if (clip.id !== id || clip.format !== 'pony-pose-atlas-clip' || !Array.isArray(clip.frames)) throw new Error('Неверный файл анимации ' + id);
      const revision = await withWorkLock(async () => { await requireRevision(expected); await writeJson(clipFile(id), clip); return workRevision(); });
      broadcast('work', {client, revision}); return reply(res, 200, {ok: true, revision, frames: clip.frames.length});
    }
    if (url.pathname === '/api/session' && req.method === 'GET') return reply(res, 200, sessions.get(session) || {});
    if (url.pathname === '/api/session' && req.method === 'PUT') { const state = {...await body(req), client}; sessions.set(session, state); broadcast('session', state, session); return reply(res, 200, {ok: true}); }
    if (url.pathname === '/api/events') {
      res.writeHead(200, {'Content-Type': 'text/event-stream', 'Cache-Control': 'no-store', Connection: 'keep-alive'});
      clients.set(client, {res, headless: url.searchParams.has('headless'), session});
      log('Подключена страница', client, 'сеанс', session, url.searchParams.has('headless') ? '(фоновая)' : '');
      const ping = setInterval(() => res.write(': ping\n\n'), 15000);
      req.on('close', () => { clearInterval(ping); clients.delete(client); log('Отключена страница', client); });
      return;
    }
    if (url.pathname === '/api/command' && req.method === 'POST') { const c = await body(req); return reply(res, 200, await runCommand(sessionName(c.session), c.name, c.args)); }
    if (url.pathname === '/api/result' && req.method === 'POST') {
      const {id, result} = await body(req), job = pending.get(id);
      if (job) { clearTimeout(job.timer); pending.delete(id); job.resolve(result); }
      return reply(res, 200, {ok: true});
    }
    reply(res, 404, {error: 'Нет такого адреса ' + url.pathname});
  } catch (error) { log('Ошибка', url.pathname, error.message); reply(res, error.status || 500, {error: error.message, ...(error.revision ? {revision: error.revision} : {})}); }
});
server.on('error', error => { console.error(error.code === 'EADDRINUSE' ? `Порт ${PORT} занят: сервер аниматора уже запущен?` : error.message); process.exit(1); });
server.listen(PORT, '127.0.0.1', () => log(`Аниматор пони: http://127.0.0.1:${PORT}/  (данные: ${STORE})`));
process.on('exit', () => { if (headlessChild) headlessChild.kill(); });
for (const signal of ['SIGINT', 'SIGTERM']) process.on(signal, () => process.exit(0));
